dashboard.definition:
{
  "title": "SAP Router",
  "description": "SAP Router connection activity, error analysis, and network boundary monitoring",
  "inputs": {
    "input_global_trp": {
      "options": {
        "defaultValue": "-30d@d,now",
        "token": "global_time"
      },
      "title": "Global Time Range",
      "type": "input.timerange"
    },
    "input_nav_dropdown": {
      "type": "input.dropdown",
      "title": "Navigate to Dashboard",
      "options": {
        "items": [
          {
            "label": "Overview",
            "value": "logserv_overview"
          },
          {
            "label": "Environment Health",
            "value": "logserv_environment_health"
          },
          {
            "label": "ABAP Security",
            "value": "logserv_abap_security"
          },
          {
            "label": "ABAP Operations",
            "value": "logserv_abap_operations"
          },
          {
            "label": "HANA Audit",
            "value": "logserv_hana_audit"
          },
          {
            "label": "HANA Trace",
            "value": "logserv_hana_trace"
          },
          {
            "label": "SAP Services",
            "value": "logserv_sap_services"
          },
          {
            "label": "Cloud Connector",
            "value": "logserv_cloud_connector"
          },
          {
            "label": "Web Dispatcher",
            "value": "logserv_web_dispatcher"
          },
          {
            "label": "Web and API Performance",
            "value": "logserv_web_api_performance"
          },
          {
            "label": "Network Perimeter",
            "value": "logserv_network_perimeter"
          },
          {
            "label": "DNS Analytics",
            "value": "logserv_dns_analytics"
          },
          {
            "label": "Linux",
            "value": "logserv_linux"
          },
          {
            "label": "Windows",
            "value": "logserv_windows"
          },
          {
            "label": "Proxy",
            "value": "logserv_proxy"
          },
          {
            "label": "Host Details",
            "value": "logserv_host_details"
          },
          {
            "label": "Cross-Stack Authentication",
            "value": "logserv_cross_stack_authentication"
          },
          {
            "label": "Change & Configuration Activity",
            "value": "logserv_change_config"
          },
          {
            "label": "Work Process Performance",
            "value": "logserv_work_process_performance"
          }
        ],
        "token": "nav_target"
      }
    }
  },
  "visualizations": {
    "viz_rect_kpi_total": {
      "options": {
        "fillColor": "#141b2d",
        "rx": 3,
        "strokeColor": "#0877a6"
      },
      "type": "splunk.rectangle"
    },
    "viz_rect_kpi_errors": {
      "options": {
        "fillColor": "#141b2d",
        "rx": 3,
        "strokeColor": "#0877a6"
      },
      "type": "splunk.rectangle"
    },
    "viz_rect_kpi_inval": {
      "options": {
        "fillColor": "#141b2d",
        "rx": 3,
        "strokeColor": "#0877a6"
      },
      "type": "splunk.rectangle"
    },
    "viz_rect_kpi_peers": {
      "options": {
        "fillColor": "#141b2d",
        "rx": 3,
        "strokeColor": "#0877a6"
      },
      "type": "splunk.rectangle"
    },
    "viz_rect_conn_trend": {
      "options": {
        "fillColor": "#141b2d",
        "rx": 3,
        "strokeColor": "#0877a6"
      },
      "type": "splunk.rectangle"
    },
    "viz_rect_error_trend": {
      "options": {
        "fillColor": "#141b2d",
        "rx": 3,
        "strokeColor": "#0877a6"
      },
      "type": "splunk.rectangle"
    },
    "viz_rect_top_peers": {
      "options": {
        "fillColor": "#141b2d",
        "rx": 3,
        "strokeColor": "#0877a6"
      },
      "type": "splunk.rectangle"
    },
    "viz_rect_return_codes": {
      "options": {
        "fillColor": "#141b2d",
        "rx": 3,
        "strokeColor": "#0877a6"
      },
      "type": "splunk.rectangle"
    },
    "viz_rect_error_detail": {
      "options": {
        "fillColor": "#141b2d",
        "rx": 3,
        "strokeColor": "#0877a6"
      },
      "type": "splunk.rectangle"
    },
    "viz_rect_conn_log": {
      "options": {
        "fillColor": "#141b2d",
        "rx": 3,
        "strokeColor": "#0877a6"
      },
      "type": "splunk.rectangle"
    },
    "viz_kpi_total": {
      "dataSources": {
        "primary": "ds_kpi_total"
      },
      "options": {
        "majorValue": "> primary | seriesByName('total') | lastPoint()",
        "sparklineValue": "> primary | seriesByName('daily')",
        "backgroundColor": "transparent",
        "labelColor": "#7b8ea8",
        "labelFontSize": 13,
        "majorColor": "#ffffff",
        "majorFontSize": 36,
        "sparklineDisplay": "below",
        "trendDisplay": "off"
      },
      "title": "Total Router Events",
      "type": "splunk.singlevalue"
    },
    "viz_kpi_errors": {
      "dataSources": {
        "primary": "ds_kpi_errors"
      },
      "options": {
        "majorValue": "> primary | seriesByName('total') | lastPoint()",
        "sparklineValue": "> primary | seriesByName('daily')",
        "backgroundColor": "transparent",
        "labelColor": "#7b8ea8",
        "labelFontSize": 13,
        "majorColor": "#dc4e41",
        "majorFontSize": 36,
        "sparklineDisplay": "below",
        "trendDisplay": "off"
      },
      "title": "Router Errors",
      "type": "splunk.singlevalue"
    },
    "viz_kpi_inval": {
      "dataSources": {
        "primary": "ds_kpi_inval"
      },
      "options": {
        "majorValue": "> primary | seriesByName('total') | lastPoint()",
        "sparklineValue": "> primary | seriesByName('daily')",
        "backgroundColor": "transparent",
        "labelColor": "#7b8ea8",
        "labelFontSize": 13,
        "majorColor": "#f1813f",
        "majorFontSize": 36,
        "sparklineDisplay": "below",
        "trendDisplay": "off"
      },
      "title": "Invalid Data Events",
      "type": "splunk.singlevalue"
    },
    "viz_kpi_peers": {
      "dataSources": {
        "primary": "ds_kpi_peers"
      },
      "options": {
        "majorValue": "> primary | seriesByName('total') | lastPoint()",
        "sparklineValue": "> primary | seriesByName('daily')",
        "backgroundColor": "transparent",
        "labelColor": "#7b8ea8",
        "labelFontSize": 13,
        "majorColor": "#ffffff",
        "majorFontSize": 36,
        "sparklineDisplay": "below",
        "trendDisplay": "off"
      },
      "title": "Unique Peer IPs",
      "type": "splunk.singlevalue"
    },
    "viz_conn_trend": {
      "dataSources": {
        "primary": "ds_conn_trend"
      },
      "options": {
        "backgroundColor": "transparent",
        "dataValuesDisplay": "off",
        "legendDisplay": "bottom",
        "seriesColorsByField": {
          "CONNECT": "#00d4b4",
          "DISCONNECT": "#7ee8fa",
          "INVAL DATA": "#f4a535"
        },
        "stackMode": "stacked",
        "xAxisLabelVisibility": "auto",
        "xAxisTitleVisibility": "hide",
        "yAxisLabelVisibility": "auto",
        "yAxisTitleVisibility": "hide"
      },
      "showLastUpdated": false,
      "showProgressBar": false,
      "title": "Connection Actions Over Time",
      "type": "splunk.column"
    },
    "viz_error_trend": {
      "dataSources": {
        "primary": "ds_error_trend"
      },
      "options": {
        "backgroundColor": "transparent",
        "dataValuesDisplay": "off",
        "legendDisplay": "bottom",
        "seriesColors": [
          "#dc4e41"
        ],
        "xAxisLabelVisibility": "auto",
        "xAxisTitleVisibility": "hide",
        "yAxisLabelVisibility": "auto",
        "yAxisTitleVisibility": "hide"
      },
      "showLastUpdated": false,
      "showProgressBar": false,
      "title": "Router Errors Over Time",
      "type": "splunk.area"
    },
    "viz_top_peers": {
      "dataSources": {
        "primary": "ds_top_peers"
      },
      "options": {
        "backgroundColor": "transparent",
        "dataValuesDisplay": "off",
        "legendDisplay": "off",
        "seriesColors": [
          "#00d4b4"
        ],
        "xAxisLabelVisibility": "auto",
        "xAxisTitleVisibility": "hide",
        "yAxisLabelVisibility": "auto",
        "yAxisTitleVisibility": "hide"
      },
      "showLastUpdated": false,
      "showProgressBar": false,
      "title": "Top Peer IPs by Connection Volume",
      "type": "splunk.bar"
    },
    "viz_return_codes": {
      "dataSources": {
        "primary": "ds_return_codes"
      },
      "options": {
        "backgroundColor": "transparent",
        "innerRadius": 0.6,
        "legendDisplay": "right",
        "legendTruncation": "ellipsisEnd",
        "seriesColors": [
          "#dc4e41",
          "#f4a535",
          "#ffcc00",
          "#9c6aff",
          "#00d4b4",
          "#7ee8fa"
        ]
      },
      "showLastUpdated": false,
      "showProgressBar": false,
      "title": "Return Code Distribution",
      "type": "splunk.pie"
    },
    "viz_error_detail": {
      "dataSources": {
        "primary": "ds_error_detail"
      },
      "eventHandlers": [
        {
          "options": {
            "newTab": true,
            "url": "/app/search/search?q=%60sap_logserv_idx_macro%60%20sourcetype%3D%22sap%3Asaprouter%22%20is_error%3D%22true%22%20error_function%3D%22$row.Function.value$%22%20%7C%20table%20_time%20error_detail%20return_code%20peer_ip%20src_ip%20source_file%20source_line%20%7C%20sort%20-_time&earliest=$global_time.earliest$&latest=$global_time.latest$"
          },
          "type": "drilldown.customUrl"
        }
      ],
      "options": {
        "backgroundColor": "transparent",
        "count": 5,
        "dataOverlayMode": "none",
        "headerBackgroundColor": "#1e2a3d",
        "rowBackgroundColorEven": "transparent",
        "rowBackgroundColorOdd": "#0d1520",
        "headerVisibility": "fixed"
      },
      "showLastUpdated": false,
      "showProgressBar": false,
      "title": "Error Detail by Function",
      "type": "splunk.table"
    },
    "viz_conn_log": {
      "dataSources": {
        "primary": "ds_conn_log"
      },
      "eventHandlers": [
        {
          "options": {
            "newTab": true,
            "url": "/app/search/search?q=%60sap_logserv_idx_macro%60%20sourcetype%3D%22sap%3Asaprouter%22%20peer_ip%3D%22$row.Peer IP.value$%22%20%7C%20table%20_time%20action%20connection_id%20peer_ip%20src_ip%20src_port%20is_error%20error_detail%20%7C%20sort%20-_time&earliest=$global_time.earliest$&latest=$global_time.latest$"
          },
          "type": "drilldown.customUrl"
        }
      ],
      "options": {
        "backgroundColor": "transparent",
        "count": 5,
        "dataOverlayMode": "none",
        "headerBackgroundColor": "#1e2a3d",
        "rowBackgroundColorEven": "transparent",
        "rowBackgroundColorOdd": "#0d1520",
        "headerVisibility": "fixed"
      },
      "showLastUpdated": false,
      "showProgressBar": false,
      "title": "Recent Connection Log",
      "type": "splunk.table"
    },
    "viz_nav_go": {
      "type": "splunk.singlevalue",
      "dataSources": {
        "primary": "ds_nav_go"
      },
      "options": {
        "majorValue": "> primary | seriesByName('label') | lastPoint()",
        "backgroundColor": "#0877a6",
        "majorColor": "#ffffff",
        "sparklineDisplay": "off",
        "trendDisplay": "off",
        "majorFontSize": 16
      },
      "eventHandlers": [
        {
          "type": "drilldown.customUrl",
          "options": {
            "url": "/app/splunk_app_sap_logserv/$nav_target$?form.global_time.earliest=$global_time.earliest$&form.global_time.latest=$global_time.latest$",
            "newTab": false
          }
        }
      ]
    }
  },
  "dataSources": {
    "ds_kpi_total": {
      "options": {
        "query": "`sap_logserv_idx_macro` sourcetype=\"sap:saprouter\" | timechart span=1d count as daily | appendpipe [stats count as _c | where _c=0 | eval _time=now(), daily=0 | fields _time daily] | eventstats sum(daily) as total",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      },
      "type": "ds.search"
    },
    "ds_kpi_errors": {
      "options": {
        "query": "`sap_logserv_idx_macro` sourcetype=\"sap:saprouter\" is_error=\"true\" | timechart span=1d count as daily | appendpipe [stats count as _c | where _c=0 | eval _time=now(), daily=0 | fields _time daily] | eventstats sum(daily) as total",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      },
      "type": "ds.search"
    },
    "ds_kpi_inval": {
      "options": {
        "query": "`sap_logserv_idx_macro` sourcetype=\"sap:saprouter\" action=\"INVAL DATA\" | timechart span=1d count as daily | appendpipe [stats count as _c | where _c=0 | eval _time=now(), daily=0 | fields _time daily] | eventstats sum(daily) as total",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      },
      "type": "ds.search"
    },
    "ds_kpi_peers": {
      "options": {
        "query": "`sap_logserv_idx_macro` sourcetype=\"sap:saprouter\" peer_ip=* | eventstats dc(peer_ip) as window_dc | timechart span=1d dc(peer_ip) as daily, max(window_dc) as total | appendpipe [stats count as _c | where _c=0 | eval _time=now(), daily=0, total=0 | fields _time daily total]",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      },
      "type": "ds.search"
    },
    "ds_conn_trend": {
      "options": {
        "query": "`sap_logserv_idx_macro` sourcetype=\"sap:saprouter\" action=* | timechart span=1d count by action",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      },
      "type": "ds.search"
    },
    "ds_error_trend": {
      "options": {
        "query": "`sap_logserv_idx_macro` sourcetype=\"sap:saprouter\" is_error=\"true\" | timechart span=1d count as \"Errors\"",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      },
      "type": "ds.search"
    },
    "ds_top_peers": {
      "options": {
        "query": "`sap_logserv_idx_macro` sourcetype=\"sap:saprouter\" peer_ip=* | stats count as \"Connections\" by peer_ip | sort -Connections | head 15 | rename peer_ip as \"Peer IP\"",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      },
      "type": "ds.search"
    },
    "ds_return_codes": {
      "options": {
        "query": "`sap_logserv_idx_macro` sourcetype=\"sap:saprouter\" return_code=* | stats count by return_code | sort -count | rename return_code as \"Return Code\"",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      },
      "type": "ds.search"
    },
    "ds_error_detail": {
      "options": {
        "query": "`sap_logserv_idx_macro` sourcetype=\"sap:saprouter\" is_error=\"true\" error_function=* | stats count as \"Count\", dc(peer_ip) as \"Unique Peers\", values(return_code) as \"Return Codes\", latest(error_detail) as \"Last Error Detail\" by error_function | sort -Count | rename error_function as \"Function\"",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      },
      "type": "ds.search"
    },
    "ds_conn_log": {
      "options": {
        "query": "`sap_logserv_idx_macro` sourcetype=\"sap:saprouter\" is_connection_event=\"true\" | eval Time=strftime(_time, \"%Y-%m-%d %H:%M:%S\") | eval has_error=if(is_error=\"true\", \"Yes\", \"No\") | table Time, action, connection_id, peer_ip, src_ip, src_port, has_error | sort -Time | head 25 | rename peer_ip as \"Peer IP\", src_ip as \"Source IP\", src_port as \"Source Port\", has_error as \"Error\", connection_id as \"Conn ID\"",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      },
      "type": "ds.search"
    },
    "ds_nav_go": {
      "type": "ds.search",
      "options": {
        "query": "| makeresults | eval label=\"Go >\"",
        "queryParameters": {
          "earliest": "-1m",
          "latest": "now"
        }
      }
    }
  },
  "layout": {
    "globalInputs": [
      "input_global_trp",
      "input_nav_dropdown"
    ],
    "layoutDefinitions": {
      "layout_1": {
        "options": {
          "backgroundColor": "#0d1117",
          "height": 1276,
          "width": 1920,
          "display": "fit-to-width"
        },
        "structure": [
          {
            "item": "viz_nav_go",
            "type": "block",
            "position": {
              "x": 10,
              "y": 10,
              "w": 120,
              "h": 25
            }
          },
          {
            "item": "viz_rect_kpi_total",
